#!/bin/bash
# The r21 candidate recipe (landed 2026-09-28, 4fb68a8..36e28e0): the canonical LH + M1 + PERF knobs,
# the r19 playability integration, the PS2 r101 world through R4IM (PS2_WORLD_MESH=1), the HUD source
# mask with the 230 lens alpha, MESH_PRIME_LAZY=1 MESH_CLIP_LEAN=1 (2026-09-28, -1.8 hw ms, STRICT kite-r21lzt). Traced (LOGIC_TRACE=1, the STRICT gate build) by default; release
# measurement adds: LOGIC_TRACE=0 GAME_DECISION_TRACE=0 ACTOR_TRANSACTION_DIAG=0 GAME_PWC_DIAG=0.
#   ASSETS=<private asset dir: leon4k/ganado runtime headers, ganado_source_extras.h, vmu_dialog_english.inc>
#   OBJDIR=<fresh objdir per knob set: never seed one objdir from another (its .d files name the old
#          targets, so edited headers/includes silently keep stale objects)>  OUT=<elf dir>
#   build-r21.sh [extra make knobs, e.g. PC_SAMPLER=1]
# Disc media: the PS2 package ps2-world.re4mesh + ps2-world.r4pw (tools/ps2_world_r4im.py) go to
# /cd/dc/native/r101/ (fixture kite-mesh-fixture-r21.json in the private evidence).
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/../../../.." && pwd)
: "${ASSETS:?private asset dir}" "${OBJDIR:?objdir}" "${OUT:?output dir}"
mkdir -p "$OBJDIR" "$OUT"
cd "$ROOT"
export RE4DC_KOS_BASE=${RE4DC_KOS_BASE:-/root/work/kos-re4dc-d367}
export PATH=$RE4DC_KOS_BASE/utils/build_wrappers:/opt/toolchains/dc/sh-elf/bin:/usr/bin:/bin
source port/dreamcast/kos-env.sh
make -C port/dreamcast/game -j4 all MESH_PRIME_LAZY=1 ACTOR_FOG_GATE=1 ACTOR_LEON_NATIVE_LOOK=1 ACTOR_SKIN_FTRV=1 ACTOR_SWAP=0 ACTOR_TRANSACTION=1 ACTOR_VTX_KERNEL=1 ACT_CAP=0 AICA_AUDIO=1 AICA_STREAMS=1 ARENA_FIT=1 BRIDGE_LEAN=1 CHAR_DATA_BLOCK=1 COARSE=1 COARSE_ACTOR_ASSET_DIR=$ASSETS COARSE_GANADO=1 COARSE_GANADO_CAST=1 COARSE_GANADO_LIMIT=-1 COARSE_GATE_ONCE=1 COARSE_LEON=1 COARSE_NO_STD_SCENERY=0 COARSE_ONE_SUBMIT=1 COARSE_PREGATE=1 COARSE_SKIN_FTRV=1 COARSE_SOURCE_ACTORS=1 COARSE_SOURCE_OBJECTS=1 COARSE_WORLD=0 COARSE_WORLD_LAYERS=0 COPY_LEAN=1 CORE_RESIDENT_BYTES=1360608 CROWD_FLAT=1 CROWD_LOD=1 CROWD_MID_M=12 CROWD_NEAR=2 CROWD_NEAR_M=5 D349_RENDERER_STACK=1 DBG_WARP=1 EFFECT_LEAN=1 EFFECT_SPRITES=1 EM10_SHARED=1 ENEMY_DEMAND=1 EVENT_FILES=1 FOG_FAR=25000 FRONT_LEAN=1 FRONT_NATIVE=1 FX_LEAN=1 GAME_ACOS_LEAN=1 GAME_ATCHK=1 GAME_ATCHK_CACHE=1 GAME_ATCHK_LIST=1 GAME_ATRECT_FAR=1 GAME_COLD_OS=1 GAME_COL_PREFETCH=1 GAME_CONCAT_COL=1 GAME_CPU=1 GAME_CUBE_MEMO=1 GAME_DECISION_TRACE=1 GAME_EM10_IDFIRST=1 GAME_EMHIT_LIST=1 GAME_ESP_OWNER=1 GAME_FP_CONTRACT=off GAME_FP_SCHED=1 GAME_FX_MOVE=1 GAME_FX_SCAN=1 GAME_HERMITE_FAST=1 GAME_HF_ASM=0 GAME_HF_INLINE=1 GAME_HF_PF=1 GAME_ID_LISTS=1 GAME_LIGHT_LAZY=1 GAME_LINE_LEAF=1 GAME_LINE_LEAF2=1 GAME_LINE_PIECE=1 GAME_LINE_TAIL=1 GAME_LINE_WALK=1 GAME_LINE_WALK_PF=1 GAME_LINE_YROW=1 GAME_MOTION_INDEX=1 GAME_MTXINV_SCHED=1 GAME_MULTVEC_SCHED=1 GAME_O2=hot GAME_OBJHIT_IDFIRST=1 GAME_OBJHIT_LIST=1 GAME_OB_DECODE=1 GAME_OB_MAT=1 GAME_OB_NEAR=1 GAME_OB_PATH=1 GAME_OB_SCAN=1 GAME_OT_MASK=1 GAME_PMC_KERNEL=1 GAME_PWC_DIAG=1 GAME_PWC_KERNEL=3 GAME_PWC_PF=1 GAME_PWC_SCHED=1 GAME_ROTVEC_MEMO=1 GAME_ROT_CACHE=1 GAME_SCEAT_LIST=1 GAME_SINCOS=1 GAME_SKEL_FTRV=1 GAME_SPHERE_WALK=1 GAME_TRIG=1 GAME_TRIG_LEAN=1 GAME_VEC_INLINE=1 GAME_VEC_NORM_INLINE=1 GAME_WORKAT_INLINE=1 GROUND_LIGHT_FIX=0 HW_LEAN=1 LINK_ORDER=$ROOT/port/dreamcast/game/link-order/r101-square-c3-8k.ld LOGIC_TRACE=1 LOGIC_TRACE_MASK_RENDER=1 MESH_DIRECT=1 MESH_LOD=1 MESH_LOD_P